#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;
using static VfxKit.VfxLightningKit;

namespace VfxEffects
{
    // Generated by vfx-shader. Rebuilt from this script: edit here, not in the Inspector.
    // Lightning running along a weapon shaft (loop), set up like rpg-game's VFX_BossRaid_Knight_Thunder Spear (read + rendered, numbers in
    // .claude/skills/vfx-shader/references/lightning-set.md). Three layers: a soft glow streak along the shaft (root), long arcs
    // (sheet 1x4) stretched along the shaft, and small arcs thrown out of a long thin ellipsoid around it. Reference root scale 0.1428 is baked
    // into the sizes; no transform has a scale; every layer is Scaling Mode Hierarchy.
    // Space (proposal): loop, shaft 2.6 m long standing upright at the origin (centre y 1.5), 3/4 camera, 3 m scale.
    public static class ThunderSpearBuild
    {
        const string Root = "Assets/VFX/ThunderSpear";
        const string Lib = "Assets/VFX/_Imported/RpgGame/Lightning/Textures/";
        const string TexGlow = Lib + "Lightning_light.png";            // soft horizontal streak, additive
        const string TexArcs = Lib + "cfxr electric arcs fade x4.png"; // 1x4 sheet of jagged arcs, additive
        const string TexSmall = Lib + "Tx_electricity_08_rot.png";     // 1x4 sheet of coloured arcs, additive
        static readonly Vector3 Centre = new Vector3(0f, 1.5f, 0f);

        [MenuItem("VFX/ThunderSpear/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");
            string M(string part) => Root + "/Materials/M_ThunderSpear_" + part + ".mat";
            var mGlow = Material(M("Glow"), VfxBlend.Additive, ImportTexture(TexGlow, 512));
            var mArcs = Material(M("Arcs"), VfxBlend.Additive, ImportTexture(TexArcs, 512));
            var mSmall = Material(M("SmallArcs"), VfxBlend.Additive, ImportTexture(TexSmall, 1024));
            ResetTiling(mGlow, mArcs, mSmall);

            // ---- root: glow streak along the shaft (reference: 2/s + a burst at 0, life 1, speed 0.01, alpha 0 -> 1 (0.21) -> 1 (0.77) -> 0)
            var root = new GameObject("VFX_ThunderSpear");
            var glow = ParticleOn(root, mGlow, lifetime: 1f, size: 1f, color: Color.white);
            Loop(glow, 5f);
            var gm = glow.main; gm.startSpeed = 0.01f; gm.maxParticles = 1000;
            TwoColors(glow, new Color(1f, 0.76f, 0.48f), new Color(1f, 0.56f, 0.13f));
            Size3D(glow, new Vector2(4.3f, 4.3f), new Vector2(1.2f, 1.2f), new Vector2(0.14f, 0.14f));
            var ge = glow.emission; ge.rateOverTime = 2f; Bursts(glow, 0f, 1);
            ConeUp(glow, Centre);
            AlphaOverLifetime(glow, 0f, 0f, 0.21f, 1f, 0.77f, 1f, 1f, 0f);
            Stretch(glow, 2f, 0f, new Vector3(0f, 0.5f, 0f), 5f, 0);

            // ---- Thunder: long arcs along the shaft (reference: rate 5 + burst, life 0.1-0.2, speed 0.1, 3D size X 1-3, Y 8-25, Z 1, sheet 1x4 random frame)
            var arcs = Layer(root.transform, "Thunder", mArcs, 0.1f, 0.2f, 0.1f, 0.1f);
            Size3D(arcs, new Vector2(0.5f, 1.2f), new Vector2(1.1f, 3.6f), new Vector2(0.14f, 0.14f));   // width x3 of the baked reference (0.14-0.43): the arc texture only fills a thin band of its frame
            TwoColors(arcs, new Color(1f, 0.82f, 0.1f), Color.white);
            var ae = arcs.emission; ae.rateOverTime = 5f; Bursts(arcs, 0f, 1);
            ConeUp(arcs, Centre);
            Sheet(arcs, 1, 4, true, true);
            Stretch(arcs, 2f, 1f, new Vector3(0f, 0.5f, 0f), 5f, 0);

            // ---- electric: small arcs out of a long thin ellipsoid around the shaft (reference: sphere r 0.6 scale (1,1,15), rate 5, life 0.15-0.3, speed 0.1-0.3, size 1-3)
            var small = Layer(root.transform, "electric", mSmall, 0.15f, 0.3f, 0.1f, 0.3f);
            var sm = small.main; sm.startSize = new ParticleSystem.MinMaxCurve(0.4f, 1.0f); sm.startColor = new Color(1f, 0.82f, 0.02f, 1f);
            var se = small.emission; se.rateOverTime = 5f;
            var sh = small.shape;
            sh.enabled = true; sh.shapeType = ParticleSystemShapeType.Sphere; sh.radius = 0.086f; sh.radiusThickness = 0f;
            sh.scale = new Vector3(1f, 1f, 15f); sh.position = Centre; sh.rotation = new Vector3(-90f, 0f, 0f);
            Sheet(small, 1, 4, false, true);
            Stretch(small, 2f, 1f, Vector3.zero, 0.5f, 2);

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_ThunderSpear.prefab");
            var look = new Vector3(0f, 1.5f, 0f);
            const float d = 7f;
            var cam = look + new Vector3(0f, Mathf.Sin(40f * Mathf.Deg2Rad) * d, -Mathf.Cos(40f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, "ThunderSpear", new[] { 0.15f, 0.4f, 0.8f, 1.3f, 1.9f, 2.6f, 3.4f, 4.4f }, cam, look);
        }

        public static void BuildBatch() => RunBatch(Build);

        // a looping layer under the root: Hierarchy scaling (kit default), no scale, life / speed ranges
        static ParticleSystem Layer(Transform parent, string name, Material mat, float lifeMin, float lifeMax, float speedMin, float speedMax)
        {
            var ps = Particle(parent, name, mat, lifetime: lifeMax, size: 1f, color: Color.white);
            Loop(ps, 5f);
            var m = ps.main; m.maxParticles = 1000;
            Range(ps, lifeMin, lifeMax, speedMin, speedMax);
            return ps;
        }
    }
}
#endif
